mapper.select:
SELECT oe.id, oe.order_request_id, oe.broker_order_no, oe.stock_code, oe.order_side,
       oe.executed_quantity, oe.executed_price, oe.executed_amount,
       oe.commission, oe.tax, oe.executed_at, oe.created_at
FROM order_execution oe
JOIN order_request req ON req.id = oe.order_request_id
WHERE oe.stock_code = #{stockCode}

  AND req.broker_type = #{mode}

ORDER BY oe.executed_at DESC, oe.id DESC
LIMIT #{limit}
